set-variable.value:
@{
    var settings = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__RATE_LIMITS_BASE64__")));
    var decision = JObject.Parse((string)context.Variables["gatewayDecision"]);
    var caller = (string)decision["callerId"];
    if (!(bool)decision["allowed"] || String.IsNullOrWhiteSpace(caller)) { throw new Exception("Authorized caller is required"); }
    var method = (string)decision["method"];
    var scope = "subscriptionKey";
    var identity = context.Subscription == null ? "" : context.Subscription.Id;
    if (method != scope || String.IsNullOrWhiteSpace(identity) || caller != "subscription:" + identity) {
      throw new Exception("Verified subscription is required");
    }
    var selected = (JObject)settings[scope];
    JToken values = selected;
    values = ((JArray)selected["overrides"]).FirstOrDefault(item => (string)item["callerId"] == caller) ?? selected;
    var profileEnabled = "{{core-subscription-profile-enabled}}" == "true";
    var hasProfile = context.Variables.ContainsKey("gatewaySubscriptionProfile");
    if (profileEnabled && !hasProfile) { throw new Exception("Subscription profile policy is not installed"); }
    var profile = hasProfile ? JObject.Parse((string)context.Variables["gatewaySubscriptionProfile"]) : new JObject();
    var profileRate = profile["requestRate"];
    var hasProfileRate = profileRate != null && profileRate.Type == JTokenType.Object;
    if (profileEnabled && hasProfileRate) { values = profileRate; }
    return new JObject(
      new JProperty("scope", scope),
      new JProperty("enabled", (profileEnabled ? hasProfileRate : (bool)selected["enabled"]) && !(bool)context.Variables["gatewayRateLimitExempt"]),
      new JProperty("calls", (int)values["calls"]),
      new JProperty("renewalPeriodSeconds", (int)values["renewalPeriodSeconds"]),
      new JProperty("counterKey", "ai-gateway-rate-v3:" + scope + ":" + Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(identity)))
    ).ToString(Newtonsoft.Json.Formatting.None);
  }
